import xml.etree.ElementTree as ET
ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
t=ET.parse('xl/styles.xml')
r=t.getroot()
print('numFmts', [(x.get('numFmtId'),x.get('formatCode')) for x in r.findall('m:numFmts/m:numFmt',ns)])
fonts=r.find('m:fonts',ns)
print('fonts count', fonts.get('count'))
for i,f in enumerate(fonts.findall('m:font',ns)):
    parts=[]
    for ch in f:
        tag=ch.tag.split('}')[1]
        if tag=='name': parts.append('name=%s'%ch.get('val'))
        elif tag=='b': parts.append('b')
        elif tag=='i': parts.append('i')
        elif tag=='u': parts.append('u=%s'%ch.get('val'))
        elif tag=='color':
            if ch.get('theme') is not None: parts.append('colorTheme=%s'%ch.get('theme'))
            else: parts.append('colorRGB=%s'%ch.get('rgb'))
        elif tag=='sz': parts.append('sz=%s'%ch.get('val'))
        elif tag=='scheme': parts.append('scheme=%s'%ch.get('val'))
        else: parts.append(tag)
    print(i, ';'.join(parts))
